import numpy as np

def problem(x: np.ndarray) -> float:
    """
    A synthetic benchmark function for global optimization, designed to approximate specific ELA features.
    """
    x = np.asarray(x)
    n = len(x)
    if x.ndim != 1:
        raise ValueError("Input x must be a 1D array.")

    summation = 0
    for i in range(n):
        for j in range(n):
            summation += (abs(x[i]**2 - x[j]**2))**2

    term1 = 0.01 * summation

    term2 = np.exp(0.2 * np.sum(x))  # Skewness influence

    return term1 + term2 + 0.001*np.sum(x**4)

import numpy as np

def problem(x: np.ndarray) -> float:
    x1, x2, x3 = x
    return (
        0.1 * np.exp(x1 - 0.2 * x2)
        + 0.5 * (x1**2 + x2**2 + x3**2)
        + 0.02 * x1 * x2
    )

import numpy as np

def problem(x: np.ndarray) -> float:
    x1, x2, x3 = x
    return (
        0.1 * np.exp(x1 - 0.2 * x2)
        + 0.5 * ((x1 - 1)**2 + (x2 + 1)**2 + x3**2)
        + 0.02 * x1 * x2
        + 0.1 * np.tanh(x1) * np.tanh(x2) * np.tanh(x3) # Added product of hyperbolic tangents
    )
